<script setup>
import {session,request} from '../session'
import {action} from '../data'
import {t} from '../i18n'
import ResourcePage from '../components/ResourcePage.vue'
const fields=editing=>[{key:'username',label:'username',required:true,disabled:!!editing},{key:'full_name',label:'contactName',required:true},{key:'password',label:editing?'newPasswordOptional':'password',type:'password',required:!editing,pattern:/^.{8,}$/,autocomplete:'new-password'},{key:'phone',label:'phone'},{key:'role',label:'role',required:true,options:[{value:'admin',label:'administrator'},{value:'agent',label:'agent'}]},{key:'is_supervisor',label:'supervisor',type:'boolean'},{key:'enabled',label:'enabled',type:'boolean'}]
async function save(values,editing){const {password,...payload}=values;const saved=await request('/api/v1/admin/users'+(editing?'/'+editing.id:''),editing?'PUT':'POST',editing?payload:{...payload,password});if(editing&&password)await request(`/api/v1/admin/users/${editing.id}/reset-password`,'POST',{password});return saved}
function future(value){return value&&new Date(value.endsWith('Z')?value:value+'Z').getTime()>Date.now()}
</script><template><ResourcePage title="users" description="usersHint" create-label="addUser" base="/api/v1/admin/users" path="/api/v1/admin/users?page=1&size=200" searchable :fields="fields" :defaults="{role:'agent',enabled:true,is_supervisor:false}" :save="save" :columns="[{key:'username',label:'username'},{key:'full_name',label:'contactName'},{key:'phone',label:'phone'},{key:'role',label:'role',tag:true},{key:'is_supervisor',label:'supervisor'},{key:'enabled',label:'enabled'},{key:'locked_until',label:'lockedUntil'},{key:'last_login_at',label:'lastLogin',date:true},{key:'created_at',label:'createdAt',date:true}]"><template #enabled="{row,reload}"><el-switch :model-value="row.enabled" :aria-label="row.username+'启用'" :disabled="row.id===session.user?.id" @change="action(()=>request('/api/v1/admin/users/'+row.id,'PUT',{enabled:!row.enabled}),{refresh:reload})"/></template><template #locked_until="{row}"><el-tag v-if="future(row.locked_until)" type="danger">{{t('lockedUntil')}} {{row.locked_until}}</el-tag><span v-else>-</span></template><template #rowActions="{row,reload}"><el-button v-if="future(row.locked_until)" link @click="action(()=>request('/api/v1/admin/users/'+row.id+'/unlock','POST'),{refresh:reload})">{{t('unlock')}}</el-button></template></ResourcePage></template>
